return ['domain'=>'publishpress-hub','plural-forms'=>'nplurals=4; plural=(n == 1 ? 0 : (n == 2 ? 1 : ((n > 10 && n % 10 == 0) ? 2 : 3)));','language'=>'he_IL','project-id-version'=>'PublishPress Hub 1.2.0','pot-creation-date'=>'2026-11-16T12:00:34+00:00','po-revision-date'=>'2026-11-16 13:09+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'PublishPress Hub','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'מרכז ניהול מרכזי עבור כל תוספי PublishPress - התקנה, עדכון וניהול רישיונות מלוח בקרה אחד.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'אנא המתן בזמן שאנו טוענים את תצוגת הרכיבים...','AI Connections'=>'חיבורים של AI','Please wait while we load AI connections...'=>'אנא המתן בזמן שאנו טוענים את חיבורי ה-AI...','Please wait while we load the plugins dashboard...'=>'אנא המתן בזמן שאנו טוענים את לוח הבקרה של התוספים...','Settings'=>'הגדרות','Please wait while we load the settings page...'=>'אנא המתן בזמן שאנו טוענים את עמוד ההגדרות...','You do not have sufficient permissions to access this page.'=>'אין לך הרשאות מספיקות לגשת לעמוד זה.','Welcome'=>'ברוך הבא','Please wait while we load the welcome page...'=>'אנא המתן בזמן שאנו טוענים את עמוד הברוך הבא...','Language pack has not been checked yet.'=>'חבילת השפה עדיין לא נבדקה.','Site locale is English. No language pack is downloaded.'=>'שפת האתר היא אנגלית. לא הורדה חבילת שפה.','No language packs are registered.'=>'אין חבילות שפה רשומות.','Language pack directory is not available.'=>'ספריית חבילות השפה אינה זמינה.','Language pack for %1$s (%2$s) matches %3$s.'=>'חבילת השפה עבור %1$s (%2$s) תואמת ל-%3$s.','Language pack for %1$s (%2$s) installed for %3$s.'=>'חבילת השפה עבור %1$s (%2$s) הותקנה עבור %3$s.','Language pack URL was rejected.'=>'כתובת ה-URL של חבילת השפה נדחתה.','Language pack download failed for %1$s (%2$s). The installed pack was left in place.'=>'ההורדה של חבילת השפה נכשלה עבור %1$s (%2$s). החבילה המותקנת נשמרה במקומה.','Language pack could not be unpacked.'=>'לא ניתן לחלץ את חבילת השפה.','Language pack is missing a catalog file. The installed pack was left in place.'=>'חבילת השפה חסרה קובץ קטלוג. החבילה המותקנת נשמרה במקומה.','Language pack JSON catalog is invalid. The installed pack was left in place.'=>'קטלוג JSON של חבילת השפה אינו תקין. החבילה המותקנת נשמרה במקומה.','Language pack could not be stored. The installed pack was left in place.'=>'לא ניתן לשמור את חבילת השפה. החבילה המותקנת נשמרה במקומה.','Language pack PHP catalog could not be built. The installed pack was left in place.'=>'לא ניתן לבנות את קטלוג PHP של חבילת השפה. החבילה המותקנת נשמרה במקומה.','Warning: The license for %1$s has expired. %2$s'=>'אזהרה: הרישיון עבור %1$s פג תוקף. %2$s','Manage licenses'=>'נהל רישיונות','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'אזהרה: ל-%1$d תוסף(ים) יש רישיונות שפג תוקפם: %2$s. %3$s','The license server accepted your key, but this site could not save its active license. Please contact support and mention this message.'=>'שרת הרישיונות קיבל את המפתח שלך, אך האתר הזה לא יכול לשמור את הרישיון הפעיל שלו. אנא פנה לתמיכה וציין את ההודעה הזו.','PublishPress actions for %s. These tools apply only to this site. If several sites are connected and the requested site is unclear, ask which site to use before calling a tool. Confirm the target site before changing site data.'=>'פעולות PublishPress עבור %s. הכלים הללו חלים רק על אתר זה. אם מספר אתרים מחוברים והאתר המבוקש אינו ברור, שאל איזה אתר להשתמש לפני קריאת כלי. אשר את האתר המיועד לפני שינוי נתוני האתר.','WordPress version'=>'גירסת WordPress','MCP Adapter version'=>'גירסת MCP Adapter','Not active'=>'לא פעיל','HTTPS'=>'HTTPS','Available'=>'זמין','Required'=>'נדרש','Application passwords'=>'סיסמאות אפליקציה','Unavailable; check WordPress or security plugin settings'=>'לא זמין; בדוק את הגדרות WordPress או תוסף האבטחה','Registered actions'=>'פעולות רשומות','Selected actions exposed'=>'פעולות נבחרות חשופות','Changes saved.'=>'שינויים נשמרו.','Changes saved. Restart your AI app or refresh its PublishPress connection to update the available actions.'=>'שינויים נשמרו. הפעל מחדש את אפליקציית ה-AI שלך או רענן את חיבור ה-PublishPress שלה כדי לעדכן את הפעולות הזמינות.','Changes saved. Connect your AI app to continue.'=>'שינויים נשמרו. חבר את אפליקציית ה-AI שלך כדי להמשיך.','Changes saved. Select at least one available action to continue.'=>'שינויים נשמרו. בחר לפחות פעולה זמינה אחת כדי להמשיך.','Update WordPress to continue'=>'עדכן את WordPress כדי להמשיך','WordPress 6.9 or newer is required.'=>'דרוש WordPress 6.9 או גרסה חדשה יותר.','Open WordPress updates'=>'פתח עדכוני WordPress','Install the MCP Adapter plugin'=>'התקן את תוסף MCP Adapter','Install the official WordPress MCP Adapter plugin to connect your AI service.'=>'התקן את תוסף MCP Adapter הרשמי של WordPress כדי לחבר את שירות ה-AI שלך.','Manage plugins'=>'נהל תוספים','Set up MCP Adapter'=>'הגדר את MCP Adapter','Use HTTPS to connect your AI'=>'השתמש ב-HTTPS כדי לחבר את ה-AI שלך','Both WordPress and site addresses must use HTTPS.'=>'גם כתובת ה-WordPress וגם כתובת האתר צריכות להשתמש ב-HTTPS.','Open site settings'=>'פתח את הגדרות האתר','Add a PublishPress plugin with AI actions'=>'הוסף תוסף PublishPress עם פעולות AI','You don\'t have any PublishPress plugins installed that support AI actions yet.'=>'אין לך תוספי PublishPress מותקנים התומכים בפעולות AI עדיין.','Open PublishPress plugins'=>'פתח תוספי PublishPress','Allow application passwords for your account'=>'אפשר סיסמאות אפליקציה עבור החשבון שלך','Create an application password in your WordPress profile for assisted or manual setup.'=>'צור סיסמת אפליקציה בפרופיל ה-WordPress שלך כדי להקים ידנית או בעזרת עזרה.','Application passwords are unavailable for your account. HTTPS or security plugin settings may need attention.'=>'סיסמאות אפליקציה אינן זמינות עבור החשבון שלך. ייתכן שהגדרות ה-HTTPS או תוסף האבטחה דורשות תשומת לב.','Open application passwords'=>'פתח סיסמאות אפליקציה','PASTE_YOUR_APPLICATION_PASSWORD_HERE'=>'PASTE_YOUR_APPLICATION_PASSWORD_HERE','Ask my AI to help'=>'שאל את ה-AI שלי לעזור','Recommended. Ask your AI for a setup script to run on your computer.'=>'מומלץ. שאל את ה-AI שלך עבור סקריפט התקנה להרצה במחשב שלך.','Connect my AI app to PublishPress. Create a setup script and give me the exact terminal command to run it.

1. Ask me to select my AI app and OS (Windows, macOS or Linux). Use interactive choices if available, otherwise numbered options.
2. Create the script using your file tools. Request the specific permission if needed. If you cannot write locally, attach a downloadable script. Only fall back to code with save instructions when neither is possible. Use PowerShell on Windows and an appropriate script on macOS or Linux. Do not stop at explaining access limitations or provide only JSON.
3. Configure this local stdio server:
Name: %3$s
Display name: %4$s
Command: npx
Arguments: -y @automattic/mcp-wordpress-remote@latest
Environment: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
Read WP_API_PASSWORD through a hidden terminal prompt.
Hub write access: %5$s. Only individually selected actions are exposed.
4. Check Node.js and npx. If missing, link to the official installer and tell me to reopen the terminal. Back up existing settings. Use a JSON/TOML parser or supported client command to merge only this server, preserving other settings and sites. Stop on invalid configuration or a conflicting endpoint. If replacing an old PublishPress desktop extension for this site, guide me to disable only that extension to avoid duplicate connections. Quote paths and values safely.
5. Give brief run, restart and approval instructions. Verify through the connection or give me a prompt to test in the app: confirm the site URL, list actual tools and perform a read-only lookup. Report whether write tools are available. If expected write tools are missing, ask me to check Allow actions that change site data and the selected actions in Hub, then refresh the connection. Do not claim success from saved configuration alone. Do not test writes during setup. Clarify the target site when ambiguous and ask for review before changing site data.'=>'חבר את אפליקציית ה-AI שלי ל-PublishPress. צור סקריפט התקנה ותן לי את הפקודה המדויקת בשורת הפקודה כדי להריץ אותו.

1. בקש ממני לבחור את אפליקציית ה-AI שלי ואת מערכת ההפעלה (Windows, macOS או Linux). השתמש בבחירות אינטראקטיביות אם זמינות, אחרת השתמש באפשרויות ממוספרות.
2. צור את הסקריפט באמצעות כלי הקבצים שלך. בקש את ההרשאה הספציפית אם נדרש. אם אינך יכול לכתוב מקומית, צרף סקריפט להורדה. חזור רק לקוד עם הוראות שמירה כאשר אף אחד מהשניים אינו אפשרי. השתמש ב-PowerShell על Windows ובסקריפט מתאים על macOS או Linux. אל תעצור בהסברת מגבלות גישה או ספק רק JSON.
3. הגדר את שרת ה-stdio המקומי הזה:
שם: %3$s
שם תצוגה: %4$s
פקודה: npx
ארגומנטים: -y @automattic/mcp-wordpress-remote@latest
סביבה: OAUTH_ENABLED=false, WP_API_URL=%1$s, WP_API_USERNAME=%2$s
קרא את WP_API_PASSWORD דרך שורת הפקודה המוסתרת.
הרשאת כתיבה על ה-Hub: %5$s. רק פעולות שנבחרו באופן אינדיבידואלי חשופות.
4. בדוק את Node.js ואת npx. אם חסר, קישור למתקין הרשמי ואמור לי לחזור לשורת הפקודה. גבה את ההגדרות הקיימות. השתמש בפארסר JSON/TOML או בפקודת לקוח נתמכת כדי למזג רק את השרת הזה, תוך שמירה על הגדרות ואתרים אחרים. עצור בהגדרה לא תקפה או בכתובת סותרת. אם מחליפים הרחבת שולחן העבודה הישנה של PublishPress עבור אתר זה, הנחה אותי לבטל רק את ההרחבה ההיא כדי למנוע חיבורים כפולים. צטט נתיבים וערכים בבטחה.
5. תן הוראות קצרות להרצה, הפעלה מחדש ואישור. אמת דרך החיבור או תן לי הנחיה לבדוק באפליקציה: אשר את כתובת האתר, רשום כלים ממשיים ובצע חיפוש לקריאה בלבד. דווח אם כלים לכתיבה זמינים. אם כלים לכתיבה צפויים חסרים, שאל אותי לבדוק לאפשר פעולות שמשנות נתוני האתר ואת הפעולות שנבחרו ב-Hub, ואז רענן את החיבור. אל תטען הצלחה רק מהגדרות שנשמרו. אל תבדוק כתיבה במהלך ההתקנה. הבהר את אתר היעד כאשר יש אי בהירות ובקש ביקורת לפני שינוי נתוני האתר.','enabled'=>'מאופשר','disabled'=>'מושבת','Set up manually'=>'הגדר ידנית','Copy the configuration into your MCP client.'=>'העתק את ההגדרה ללקוח ה-MCP שלך.','Actions available through PublishPress Hub.'=>'פעולות זמינות דרך Hub של PublishPress.','List WordPress users'=>'רשימת משתמשי WordPress','Find users by name or role. The optional primitive capability filter checks effective access within each candidate page. Visit all total_pages even when a filtered page is empty. No email addresses or secrets are returned.'=>'מצא משתמשים לפי שם או תפקיד. מסנן היכולת הפרימיטיבית האופציונלי בודק גישה אפקטיבית בתוך כל עמוד מועמד. בקר בכל total_pages גם כאשר עמוד מסונן ריק. אין כתובות דוא"ל או סודות מוחזרים.','Get WordPress user capabilities'=>'קבל את יכולות המשתמש של WordPress','Resolve exactly one user_id or username and return their identity, roles and effective primitive capabilities. Never guess a user ID. Object-specific permissions require a separate check for that object.'=>'פתור בדיוק user_id או שם משתמש אחד והחזר את הזהות, התפקידים והיכולות הפרימיטיביות האפקטיביות שלהם. לעולם אל תנחש ID של משתמש. הרשאות ספציפיות לאובייקט דורשות בדיקה נפרדת עבור אותו אובייקט.','Find WordPress content'=>'מצא תוכן של WordPress','Search readable posts, pages or a REST-enabled custom post type. Returns actual IDs, titles and permalinks. Use post_type=page for pages. Resolve ambiguous titles before using a URL. Default status is publish. Private and draft requests enforce WordPress permissions.'=>'חפש פוסטים, עמודים או סוג פוסט מותאם REST שניתן לקרוא. מחזיר ID, כותרות וכתובות קבועות אמיתיות. השתמש post_type=page עבור עמודים. פותר כותרות לא ברורות לפני השימוש בכתובת URL. הסטטוס ברירת המחדל הוא פרסום. בקשות פרטיות ודראפט אוכפות הרשאות של WordPress.','List WordPress post types'=>'רשום סוגי פוסטים של WordPress','List readable REST-enabled post types and the capability names used for each type. Use these names for content lookups and permission questions.'=>'רשום סוגי פוסטים שניתן לקרוא המותאמים ל-REST ואת שמות היכולות המשמשות לכל סוג. השתמש בשמות אלו לחיפושי תוכן ושאלות הרשאה.','WordPress'=>'WordPress','Create WordPress user'=>'צור משתמש WordPress','Create a new user account with a known username, email and one editable role. Ask for missing details. WordPress validates role assignment permissions. MCP rejects administrator and any role granting administrator-level capabilities. A password is generated privately. By default WordPress emails the user a password setup link. Never guess an email or request a password in chat.'=>'צור חשבון משתמש חדש עם שם משתמש ידוע, דוא"ל ותפקיד אחד שניתן לעריכה. בקש פרטים חסרים. WordPress מאמת את הרשאות ההקצאה של התפקיד. MCP דוחה מנהלים וכל תפקיד שנותן הרשאות ברמת מנהל. סיסמה נ生成ת באופן פרטי. ברירת המחדל היא ש-WordPress שולחת למשתמש קישור להקצאת סיסמה. אל תנסה לנחש דוא"ל או לבקש סיסמה בצ\'אט.','Create WordPress content'=>'צור תוכן WordPress','Create a post, page or REST-enabled custom post type. Use post_type=page for pages. Defaults to draft. Publish or schedule only when requested. WordPress checks creation, publishing and author-assignment permissions. Returns the actual ID and permalink.'=>'צור פוסט, עמוד או סוג פוסט מותאם REST. השתמש ב-post_type=page עבור עמודים. ברירת המחדל היא טיוטה. פרסם או קבע מועד רק כאשר מתבקש. WordPress בודק את הרשאות ההקמה, הפרסום וההקצאה של המחבר. מחזיר את ה-ID והקישור הקבוע בפועל.','Update WordPress content'=>'עדכן תוכן WordPress','Edit an existing post, page or REST-enabled custom post by its verified ID. Find content first if the ID is unknown. Only supplied fields change. WordPress checks object, publishing and author-assignment permissions. No deletion, arbitrary metadata or options are supported.'=>'ערוך פוסט, עמוד או פוסט מותאם REST קיים לפי ה-ID המאומת שלו. מצא תוכן קודם אם ה-ID אינו ידוע. רק השדות שסופקו משתנים. WordPress בודק את ההגדרה, הפרסום וההקצאה של המחבר. אין תמיכה במחיקה, מטא-נתונים שרירותיים או אפשרויות.','Use the exact input types shown in discovery.'=>'השתמש בסוגי הקלט המדויקים המוצגים בגילוי.','You cannot list users.'=>'אינך יכול לרשום משתמשים.','Provide either a user ID or an exact username.'=>'ספק או ID משתמש או שם משתמש מדויק.','No matching user belongs to this site.'=>'אין משתמש תואם ששייך לאתר זה.','You cannot inspect this user.'=>'אינך יכול לבדוק משתמש זה.','Choose a REST-enabled post type.'=>'בחר סוג פוסט מותאם REST.','This post type does not support content lookup.'=>'סוג הפוסט הזה אינו תומך בחיפוש תוכן.','MCP tools cannot create users with administrator-level access. Use the WordPress Users screen for this change.'=>'כלים של MCP אינם יכולים ליצור משתמשים עם גישה ברמת מנהל. השתמש במסך משתמשי WordPress לשינוי זה.','Provide at least one content field to update.'=>'ספק לפחות שדה תוכן אחד לעדכון.','Choose an existing REST-enabled post type.'=>'בחר סוג פוסט מותאם REST קיים.','This post type does not support content writes.'=>'סוג הפוסט הזה אינו תומך בכתיבת תוכן.','You cannot perform this operation.'=>'אינך יכול לבצע פעולה זו.','Object must be loaded before initializing.'=>'העצם חייב להיות טעון לפני אתחול.','This license key is managed in wp-config.php and cannot be edited from the Hub.'=>'מפתח רישוי זה מנוהל ב-wp-config.php ואינו ניתן לעריכה מהממרכז.','No license key found'=>'לא נמצא מפתח רישוי','This license key is managed in wp-config.php and cannot be deactivated from the Hub.'=>'מפתח רישוי זה מנוהל ב-wp-config.php ואינו ניתן להשבתה מהממרכז.','Invalid conflict resolution request.'=>'בקשת פתרון קונפליקט לא תקפה.','The selected plugin is not available for activation.'=>'הפלאגין שנבחר אינו זמין להפעלה.','Cleanup was stopped because the selected plugin is not active or the other version is still loaded. Neither copy was deleted.'=>'ניקוי הופסק כי הפלאגין שנבחר אינו פעיל או שהגרסה האחרת עדיין טעונה. אף עותק לא נמחק.','The selected plugin is active, but the other version could not be removed. Please remove it from the Plugins screen.'=>'הפלאגין שנבחר פעיל, אך לא ניתן היה להסיר את הגרסה האחרת. יש להסיר אותה ממסך הפלאגינים.','The selected plugin is no longer active. Please reactivate it from the Plugins screen.'=>'הפלאגין שנבחר אינו פעיל עוד. יש להפעיל אותו מחדש ממסך הפלאגינים.','No existing license key was found for this plugin.'=>'לא נמצא מפתח רישוי קיים עבור פלאגין זה.','Database Tables'=>'טבלאות מסד נתונים','PublishPress Plugins'=>'פלאגיני PublishPress','PublishPress Hub Debug Log'=>'יומן דיבוג של PublishPress Hub','Debug Log'=>'יומן דיבוג','The debug log is empty.'=>'יומן הדיבוג ריק.','Version'=>'גרסה','Debug Mode'=>'מצב דיבוג','Enabled'=>'מופעל','Disabled'=>'מכובה','Generated At'=>'נוצר ב','Plugins'=>'פלאגינים','No PublishPress plugins found.'=>'לא נמצאו פלאגיני PublishPress.','Tables'=>'טבלאות','No database table information was available.'=>'לא הייתה מידע על טבלת מסד נתונים.','Size'=>'גודל','Engine'=>'מנוע','Rows'=>'שורות','Collation'=>'שילוב','Charset'=>'סט字符ים','Total Database Size'=>'גודל מסד הנתונים הכולל','Not installed'=>'לא מותקן','Active'=>'פעיל','Inactive'=>'לא פעיל','unknown'=>'לא ידוע','License'=>'רשיון','Free plugin not set for plugin family: %s'=>'תוסף חינם לא הוגדר למשפחת תוספים: %s','Pro plugin not set for plugin family: %s'=>'תוסף פרו לא הוגדר למשפחת תוספים: %s','License activation error. Please try again later or contact support for help.'=>'שגיאת הפעלת רשיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','License deactivation error. Please try again later or contact support for help.'=>'שגיאת השבתת רשיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This license is currently disabled. Please contact support for help.'=>'הרשיון הזה מושבת כרגע. אנא פנה לתמיכה לעזרה.','This license has expired. Please contact support to renew it.'=>'הרשיון הזה פג תוקף. אנא פנה לתמיכה כדי לחדש אותו.','This license key could not be activated. It may be invalid, blocked, or not authorized for this plugin. Please verify the key and contact PublishPress support if the problem continues.'=>'לא ניתן היה להפעיל את מפתח הרשיון הזה. ייתכן שהוא לא תקף, חסום, או לא מורשה עבור תוסף זה. אנא אשר את המפתח ופנה לתמיכת PublishPress אם הבעיה נמשכת.','This license cannot be used for this plugin. Please contact support for help.'=>'הרשיון הזה לא יכול לשמש עבור תוסף זה. אנא פנה לתמיכה לעזרה.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'הרשיון הזה אינו תואם את התוסף שאתה מנסה להפעיל. אנא פנה לתמיכה לעזרה.','License key does not match our records. Please contact support for assistance.'=>'מפתח הרשיון אינו תואם את הרשומות שלנו. אנא פנה לתמיכה לעזרה.','No license key provided. Please enter a valid license key.'=>'לא סופק מפתח רשיון. אנא הכנס מפתח רשיון תקף.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'כתובת ה-URL של האתר שלך נדרשת כדי להפעיל את הרשיון. אנא הכנס כתובת URL תקפה של האתר כדי להמשיך.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'הגעת למגבלת הפעלת הרשיון. אנא פנה לתמיכה כדי לשדרג או להשבית באתר אחר.','This license cannot be activated. Please contact support for help.'=>'לא ניתן להפעיל את הרשיון הזה. אנא פנה לתמיכה לעזרה.','License server error. Please try again later or contact support for help.'=>'שגיאת שרת הרשיון. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','The license server returned an invalid response. Please try again later or contact support for help.'=>'שרת הרשיון החזיר תגובה לא תקפה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This license is inactive for this site. Please contact support for help.'=>'הרשיון הזה אינו פעיל עבור אתר זה. אנא פנה לתמיכה לעזרה.','Plugin activation failed. Please try again later or contact support for help.'=>'הפעלת התוסף נכשלה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','This action is not possible because the plugin is already installed.'=>'פעולה זו אינה אפשרית מכיוון שהתוסף כבר מותקן.','Plugin deactivation failed. Please try again later or contact support for help.'=>'השבתת התוסף נכשלה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','Plugin family not found. Please contact support for help.'=>'לא נמצאה משפחת תוספים. אנא פנה לתמיכה לעזרה.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'פעולה זו אינה אפשרית מכיוון ששני הגרסאות החינמיות והפרו מותקנות. אנא הסר גרסה אחת כדי להמשיך.','Plugin installation failed. Please contact support for help.'=>'התקנת התוסף נכשלה. אנא פנה לתמיכה לעזרה.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'פעולה זו אינה אפשרית מכיוון שהתוסף אינו מופעל. אנא הפעל את התוסף ונסה שוב.','Plugin not found in our available plugins list. Please contact support for help.'=>'התוסף לא נמצא ברשימת התוספים הזמינים שלנו. אנא פנה לתמיכה לעזרה.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'פעולה זו אינה אפשרית מכיוון שהתוסף אינו מותקן. אנא התקן את התוסף ונסה שוב.','Unknown license server error. Please try again later or contact support for help.'=>'שגיאת שרת רשיון לא ידועה. אנא נסה שוב מאוחר יותר או פנה לתמיכה לעזרה.','Sell digital products, programs, and services from your website.'=>'מכור מוצרים דיגיטליים, תוכניות ושירותים מהאתר שלך.','Create and manage tags, categories, and taxonomy terms.'=>'צור וניהול תגיות, קטגוריות ומונחי טקסונומיה.','Organize taxonomy terms into groups and display them in clouds, tabs, and lists.'=>'ארגן את מונחי הטקסונומיה לקבוצות והצג אותם בעננים, טאבים ורשימות.','Define tasks that authors must complete before publishing.'=>'הגדר משימות שעל הכותבים להשלים לפני הפרסום.','Control who can edit and view your content.'=>'שלוט מי יכול לערוך ולצפות בתוכן שלך.','Create, manage and display authors for your content.'=>'צור, נהל והצג כותבים עבור התוכן שלך.','All the tools you need to improve the block editor.'=>'כל הכלים שאתה צריך כדי לשפר את עורך הבלוקים.','Control your admin area and user roles.'=>'שלוט באזור הניהול שלך ותפקידי המשתמשים.','Schedule changes to your posts.'=>'תזמן שינויים בפוסטים שלך.','Organize, schedule, and plan your publishing.'=>'ארגן, תזמן ותכנן את הפרסום שלך.','Approve and schedule new versions to your published posts.'=>'אשר ותזמן גרסאות חדשות לפוסטים שפורסמו שלך.','Organize your posts into issues or series.'=>'ארגן את הפוסטים שלך לגליונות או סדרות.','Create custom URLs for your posts and external links.'=>'צור כתובות URL מותאמות אישית לפוסטים שלך וללינקים חיצוניים.','Create custom statuses and publishing workflows.'=>'צור סטטוסים מותאמים אישית וזרימות עבודה לפרסום.','Dependency "%s" not found in container.'=>'תלות "%s" לא נמצאה בקונטיינר.','Error validating license: %s'=>'שגיאה באימות רישיון: %s','Error getting license info: %s'=>'שגיאה בקבלת מידע רישיון: %s','The license server denied this request. This can happen when a license key or site has been blocked. Please contact PublishPress support for help.'=>'שרת הרישוי דחה את הבקשה הזו. זה יכול לקרות כאשר מפתח רישוי או אתר חסומים. אנא פנה לתמיכה של PublishPress לעזרה.','Too many requests. Please try again later.'=>'יותר מדי בקשות. אנא נסה שוב מאוחר יותר.','An error occurred while processing your request.'=>'אירעה שגיאה בעת עיבוד הבקשה שלך.','Template not found: %s'=>'התבנית לא נמצאה: %s','Path cannot be empty'=>'המסלול לא יכול להיות ריק','File extension cannot be empty'=>'סיומת הקובץ לא יכולה להיות ריקה','Invalid file path: null byte detected'=>'נתיב קובץ לא חוקי: זיהוי בית נאלץ','Invalid file path: directory traversal detected'=>'נתיב קובץ לא חוקי: זיהוי חציית תיקייה','Invalid file path: parent directory does not exist: %s'=>'נתיב קובץ לא חוקי: תיקיית ההורה אינה קיימת: %s','Invalid file path: unable to resolve path'=>'נתיב קובץ לא חוקי: לא ניתן לפתור את הנתיב','Invalid file path: operation not allowed outside permitted directories'=>'נתיב קובץ לא חוקי: פעולה אינה מותרת מחוץ לתיקיות המותרות','Download URL failed WordPress validation'=>'URL ההורדה לא עמד באימות WordPress','Downloaded plugin file does not exist'=>'קובץ התוסף שהורד אינו קיים','Downloaded plugin file is empty'=>'קובץ התוסף שהורד ריק','Cannot read downloaded plugin file'=>'לא ניתן לקרוא לקובץ התוסף שהורד','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'הקובץ שהורד אינו ארכיון ZIP תקין. ייתכן ש-URL ההורדה מחזיר דף שגיאה.','Failed to unzip plugin file: %s'=>'נכשל בהוצאת קובץ התוסף: %s','Failed to unzip plugin file'=>'נכשל בהוצאת קובץ התוסף','Failed to activate plugin: %s'=>'נכשל בהפעלה של תוסף: %s','Resolve conflicts for network-active plugins from Network Admin.'=>'פתור סכסוכים עבור תוספים פעילים ברשת ממנהל הרשת.','Activation recovery failed. Both plugin copies were retained. Please restore the previous version from the Plugins screen.'=>'שחזור ההפעלה נכשל. שני העותקים של התוסף נשמרו. אנא שחזר את הגרסה הקודמת ממסך התוספים.','The other plugin could not be deactivated.'=>'התוסף השני לא יכול היה להתבטל.','The selected plugin did not remain active.'=>'התוסף שנבחר לא נשאר פעיל.','The selected plugin could not be activated. Neither copy was deleted and the previous activation settings were restored.'=>'לא ניתן להפעיל את התוסף שנבחר. אף עותק לא נמחק וההגדרות הקודמות של ההפעלה שוחזרו.','Failed to delete plugin: %s'=>'נכשל במחיקת תוסף: %s','No update available for this plugin'=>'אין עדכון זמין עבור תוסף זה','Invalid update information for this plugin'=>'מידע על עדכון לא תקין עבור תוסף זה','Update package not available'=>'חבילת העדכון אינה זמינה','Failed to update plugin: %s'=>'נכשל בעדכון התוסף: %s','Plugin update failed'=>'עדכון התוסף נכשל','Invalid download URL provided'=>'כתובת ה-URL להורדה שסופקה אינה תקינה','Download URL must use HTTP or HTTPS protocol'=>'כתובת ה-URL להורדה חייבת להשתמש בפרוטוקול HTTP או HTTPS','Download URL is not from an allowed domain: %s'=>'כתובת ה-URL להורדה אינה מדומיין מותר: %s','Could not create a temporary package file'=>'לא ניתן ליצור קובץ חבילה זמני','Failed to download plugin: %s'=>'נכשל בהורדת התוסף: %s','The plugin package download failed'=>'ההורדה של חבילת התוסף נכשלתה','Failed to get plugin information: %s'=>'נכשל בקבלת מידע על התוסף: %s','MCP Adapter could not be installed or activated. Use the plugin page or contact your host.'=>'לא ניתן להתקין או להפעיל את מתאם MCP. השתמש בדף התוסף או צור קשר עם המארח שלך.','MCP Adapter activated.'=>'מתאם MCP הופעל.','ERR'=>'ERR','.'=>'.']];